<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';
$rawId = $_GET['id'] ?? null;
$id = is_string($rawId) ? filter_var($rawId, FILTER_VALIDATE_INT, ['options'=>['min_range'=>1]]) : false;
if (!$id) abort_request(404, 'Dieses Angebot wurde nicht gefunden.');
$origin=null;$originPostal=$_GET['origin_zip']??'';$originCountry=$_GET['origin_country']??geo_country();
if(!is_string($originPostal)||!is_string($originCountry))abort_request(400,t('Ungültiger Standortfilter.'));
try{if($originPostal!=='')$origin=geo_postcode($pdo,geo_country($originCountry),$originPostal);}catch(InvalidArgumentException $e){abort_request(400,t($e->getMessage()));}
$item = market_find($pdo, (int)$id, true,$origin);
if ($item === null) abort_request(404, 'Dieses Angebot ist nicht verfügbar.');
$isAuction = $item['type'] === 'auction';
if ($isAuction && empty($forceAuction)) redirect('/marketplace/view-auction.php?id=' . (int)$id);
if (!$isAuction && !empty($forceAuction)) redirect('/marketplace/view-item.php?id=' . (int)$id);
$user = current_user($pdo);
if ($user && ($_SERVER['REQUEST_METHOD']??'')==='GET') personal_record_view($_SESSION,(int)$user['id'],$item);
$isOwner = $user && (int)$user['id'] === (int)$item['seller_id'];
$hasEnded = $item['status'] !== 'active' || ($isAuction && $item['ends_at'] !== null && strtotime($item['ends_at'] . ' UTC') <= time());
$price = $isAuction && $item['current_bid_cents'] !== null ? (int)$item['current_bid_cents'] : (int)$item['price_cents'];
$canContact = !$isOwner && (!$hasEnded || ($user && (int)($item['highest_bidder_id'] ?? 0) === (int)$user['id']));
$imageCount = max(1, min(5, (int)($item['image_count'] ?? 0)));
$history = $isAuction ? market_public_bid_history($pdo, (int)$id, 20) : [];
$pageTitle = $item['title'];
$pageDescription = substr($item['description'], 0, 160);
$seoListing = $item;
include __DIR__ . '/../includes/header.php';
?>
