<div class="listing-layout"><div><section class="listing-gallery reveal" aria-label="<?=h(t('Produktbilder'))?>" data-gallery><div class="gallery-main"><img src="/marketplace/image.php?id=<?= (int)$id ?>&amp;position=0&amp;size=large" width="1000" height="800" alt="<?= h($item['title']) ?> – <?=h(t('Ansicht'))?> 1" data-gallery-main fetchpriority="high"></div><?php if ($imageCount > 1): ?><div class="gallery-thumbs"><?php for ($position=0; $position<$imageCount; $position++): ?><a href="/marketplace/image.php?id=<?= (int)$id ?>&amp;position=<?= $position ?>&amp;size=large" data-gallery-src="/marketplace/image.php?id=<?= (int)$id ?>&amp;position=<?= $position ?>&amp;size=large" data-gallery-alt="<?= h($item['title']) ?> – <?=h(t('Ansicht'))?> <?= $position+1 ?>" <?= $position === 0 ? 'aria-current="true"' : '' ?>><img src="/marketplace/image.php?id=<?= (int)$id ?>&amp;position=<?= $position ?>&amp;size=thumb" alt="Ansicht <?= $position+1 ?> anzeigen" width="100" height="100" loading="lazy"></a><?php endfor; ?></div><?php endif; ?></section><section class="listing-story"><h2> <?=h(t('Die Geschichte zum Stück.'))?> </h2><div class="listing-description"><?= h($item['description']) ?></div></section>
<?php if ($isAuction): ?><section class="bid-history"><h2> <?=h(t('Öffentlicher Gebotsverlauf'))?> </h2><?php if ($history === []): ?><p class="muted"><?=h(t('Noch keine Gebote. Private Maximalgebote erscheinen hier nicht.'))?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th> <?=h(t('Ereignis'))?> </th><th> <?=h(t('Betrag'))?> </th><th> <?=h(t('Zeitpunkt (UTC)'))?> </th></tr></thead><tbody><?php foreach ($history as $event): ?><tr><td><?= h(['bid'=>t('Gebot'),'buyout'=>t('Sofortkauf'),'close'=>t('Abschluss'),'close_no_bid'=>t('Ohne Gebot beendet')][$event['event_type']] ?? t('Ereignis')) ?></td><td><?= $event['amount_cents'] === null ? '–' : h(money_eur((int)$event['amount_cents'])) ?></td><td><?= h($event['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="help"><?=h(t('Angezeigt werden veröffentlichte Preise. Hinterlegte Maximalgebote bleiben privat.'))?></p><?php endif; ?></section><?php endif; ?>
</div><aside class="listing-information reveal"><span class="badge <?= $isAuction ? 'accent' : 'muted' ?>"><?= $isAuction ? t('Auktion') : t('Festpreis') ?></span><h1><?= h($item['title']) ?></h1><div class="detail-location"><?= ui_icon('pin') ?><?= h($item['country_code'].' · '.$item['zip'] . ' ' . $item['city']) ?></div><p class="country-summary"><?=h(geo_countries()[$item['country_code']]??$item['country_code'])?></p>
<form class="location-origin-form" method="get"><input type="hidden" name="id" value="<?=(int)$id?>"><label class="field"><?=h(t('Bezugsland'))?><select name="origin_country"><?php foreach(geo_active_countries($pdo) as $code=>$name):?><option value="<?=h($code)?>" <?=$originCountry===$code?'selected':''?>><?=h($name)?></option><?php endforeach;?></select></label><label class="field"><?=h(t('Postleitzahl'))?><input name="origin_zip" value="<?=h($originPostal)?>" maxlength="16" autocomplete="postal-code" required></label><button class="button secondary" type="submit"><?=h(t('Entfernung'))?></button></form>
<?php if($originPostal!==''):?><p class="help"><?=h(geo_distance_label($item['distance_km']??null))?></p><p class="help"><?=h(t('Entfernungen sind ungefähre Luftlinien zwischen PLZ-Mittelpunkten, keine Straßenentfernungen.'))?></p><?php endif;?>
<div class="detail-price"><?= h(money_eur($price)) ?></div><p class="detail-price-label"><?= $isAuction ? ($item['current_bid_cents'] === null ? t('Startpreis') : t('Aktuelles Höchstgebot')) : t('Angebotspreis') ?></p>
<?php if ($hasEnded): ?><div class="notice"><?= $item['status'] === 'active' ? 'Die Gebotsfrist ist abgelaufen. Der serverseitige Abschluss wird verarbeitet.' : ($item['status'] === 'sold' ? 'Dieses Angebot wurde als verkauft markiert.' : 'Diese Auktion ist beendet.') ?></div><?php endif; ?>
<?php if ($isAuction && !$hasEnded): ?><section class="auction-panel panel"><div class="auction-time"><?= ui_icon('clock') ?><span> <?=h(t('Verbleibende Gebotszeit'))?> </span></div><div class="countdown" data-countdown="<?= h(str_replace(' ', 'T', $item['ends_at']) . 'Z') ?>"><?= h($item['ends_at']) ?> UTC</div><?php if ($isOwner): ?><p class="help"><?=h(t('Du kannst auf dein eigenes Angebot nicht bieten.'))?></p><?php elseif ($user): ?><?php if ((int)($item['highest_bidder_id'] ?? 0) === (int)$user['id']): ?><p class="notice success"> <?=h(t('Du hältst das führende Gebot.'))?> </p><?php endif; ?><form action="/actions/place-bid.php" method="post"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$id ?>"><label class="field"> <?=h(t('Dein privates Maximalgebot (€)'))?> <input name="max_bid" inputmode="decimal" maxlength="14" required placeholder="Zum Beispiel 50,00" autocomplete="off"></label><button class="button" type="submit"><?=h(t('Gebot abgeben'))?><?= ui_icon('arrow') ?></button></form><p class="help"><?=h(t('Das System bietet nur so weit wie nötig. Ein gültiges Gebot in den letzten zwei Minuten verlängert die Frist auf mindestens zwei Minuten.'))?></p><?php else: ?><a class="button" href="/auth/login.php"><?=h(t('Zum Bieten anmelden'))?><?= ui_icon('arrow') ?></a><?php endif; ?></section><?php endif; ?>
<div class="detail-actions"><?php if ($isOwner && !$hasEnded): ?><a class="button" href="/user/edit-listing.php?id=<?= (int)$id ?>"><?=h(t('Inserat bearbeiten'))?><?= ui_icon('arrow') ?></a><?php elseif ($canContact): ?><a class="button <?= $isAuction ? 'secondary' : '' ?>" href="<?= $user ? '/user/chat.php?listing_id=' . (int)$id . '&user_id=' . (int)$item['seller_id'] : '/auth/login.php' ?>"><?=h(t('Verkäufer kontaktieren'))?><?= ui_icon('arrow') ?></a><?php endif; ?>
<?php if ($user && !$isOwner && !$hasEnded): ?><form method="post" action="/user/toggle-watchlist.php"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$id ?>"><button class="button secondary" type="submit"><?= ui_icon('heart') ?><?=h(t('Merkliste ändern'))?></button></form><?php endif; ?>
<?php if ($user && !$hasEnded): ?><form method="post" action="/user/personal.php"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="listing_id" value="<?=(int)$id?>"><button class="button secondary" type="submit"><?=h(t('personal.add'))?></button></form><?php endif; ?>
<?php if ($isAuction && !$hasEnded && !$isOwner && (int)($item['buyout_cents'] ?? 0) > 0 && $item['current_bid_cents'] === null): ?><form method="post" action="/marketplace/buyout-request.php?id=<?= (int)$id ?>"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$id ?>"><button class="button secondary" type="submit"><?=h(t('Sofort kaufen'))?> · <?= h(money_eur((int)$item['buyout_cents'])) ?></button></form><?php endif; ?>
<?php if ($isAuction && $item['status'] === 'ended' && $user && !empty($item['highest_bidder_id']) && ($isOwner || (int)$item['highest_bidder_id'] === (int)$user['id'])): ?><a class="button secondary" href="/user/rate-user.php?listing_id=<?= (int)$id ?>"><?=h(t('Transaktionspartner bewerten'))?><?= ui_icon('arrow') ?></a><?php endif; ?></div>
